    var trim = function(a){ return a; };
  }

  var hollaback = function( error, stdout, stderr ) {
    if ( error !== null ) {
      dfd.reject( error, stdout, stderr, command );
    } else {
      dfd.resolve( trim( stdout ), trim( stderr ), command );
    }
  };

  if ( type === 'file' ) {
